function currentTask(){return tasks[state.task]||tasks[0]||{name:'每日签到',desc:'每天一点，积累小确幸',icon:'sun',color:'',type:'脚本任务'};}
function action(label,act,cls='primary',ic=''){return `<button class="${cls}" data-action="${esc(act)}">${ic?icon(ic):''}${label}</button>`;}
function go(label,page,cls='primary',ic=''){return `<button class="${cls}" data-go="${page}">${ic?icon(ic):''}${label}</button>`;}
function ib(ic,act,label){return `<button class="icon-btn" data-action="${act}" aria-label="${label}">${icon(ic)}</button>`;}
function pill(text,tone=''){if(!tone&&/已开启|成功|已完成|运行中|正在执行|就绪|已导入|实时/.test(text))tone='success';return `<span class="pill ${tone}">${text}</span>`;}
function section(text,right=''){return `<div class="section-title">${text}${right?`<small>${right}</small>`:''}</div>`;}
function row(title,desc,ic,target,tail='',tone=''){return `<button class="setting-row" ${target?.startsWith('@')?`data-action="${esc(target.slice(1))}"`:`data-go="${target||'tasks'}"`}><span class="app-icon ${tone}">${icon(ic)}</span><span class="item-copy"><span class="title">${title}</span>${desc?`<span class="desc" style="display:block">${desc}</span>`:''}</span>${tail||icon('chevron','row-arrow')}</button>`;}
function card(rows){return `<div class="list-card">${rows}</div>`;}
function note(text,tone=''){return `<div class="note ${tone}">${text}</div>`;}
function field(label,value='',type='text',id='',hint=''){return `<label class="field"><span>${label}</span><input ${id?`data-field="${id}"`:''} type="${type}" value="${esc(value)}" ${type==='number'?'min="0"':''}>${hint?`<small>${hint}</small>`:''}</label>`;}
function toggle(on,id,label){return `<button class="toggle ${on?'on':''}" data-action="toggle:${id}" role="switch" aria-checked="${on}" aria-label="${label}"></button>`;}
function choice(title,desc,selected,act,ic=''){return `<button class="choice ${selected?'selected':''}" data-action="${act}" role="radio" aria-checked="${selected}">${ic?`<span class="app-icon">${icon(ic)}</span>`:''}<span><h4>${title}</h4><p>${desc}</p></span><span class="radio"></span></button>`;}
function check(on){return `<span class="check ${on?'checked':''}">${on?icon('check'):''}</span>`;}
function header(title,subtitle='',back=true,actions=''){return `<header class="mobile-header ${back?'sub':'main'}">${back?ib('back','back','返回'):''}<div class="header-text"><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions}</header>`;}
function nav(active){return `<nav class="bottom-nav" aria-label="APP 主导航">${[['tasks','tasks','任务'],['logs','log','日志'],['permissions','shield','权限'],['settings','settings','设置']].map(([id,ic,t])=>`<button data-go="${id}" class="${active===id?'active':''}"><span class="nav-icon">${icon(ic)}</span>${t}</button>`).join('')}</nav>`;}
function screen(body,{title='',subtitle='',back=true,actions='',tab='',footer='',cls=''}={}){return {body:`${title?header(title,subtitle,back,actions):''}<div class="${cls||'app-pad'}">${body}</div>`,tab,footer};}
function taskRow(t,i,{select=false,reorder=false,number=false,selected=state.selected.has(i)}={}){return `<button class="task-row" ${reorder?`draggable="true" data-task-index="${i}"`:''} ${select?`data-action="select:${i}"`:`data-action="task:${i}"`}>${number?`<span class="step-number">${String(typeof number==='number'?number:i+1).padStart(2,'0')}</span>`:''}<span class="app-icon ${t.color}">${icon(t.icon)}</span><span class="item-copy"><span class="title">${esc(t.name)}</span><span class="desc" style="display:block">${esc(t.desc)}</span></span>${select?check(selected):t.tag?pill(t.tag):icon('chevron','row-arrow')}</button>`;}
function empty(title,desc,ic,button='',target='create'){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${title}</h3><p>${desc}</p>${button?go(button,target,'primary','plus'):''}</div>`;}
function hero(title,subtitle,foot,ic='bird'){return `<div class="hero"><span class="overline">A LITTLE LESS REPETITION</span><h3>${title}</h3><p>${subtitle}</p>${ic==='bird'?bird():''}<div class="hero-bottom">${foot}</div></div>`;}
