define('editor','脚本编辑器','edit','专注代码的深色编辑区，保留示例、保存、API 提示、清空与行列位置。未保存离开和流程转脚本均需确认。',()=>({body:`${header('脚本编辑',esc(currentTask().name),true,go('示例','examples','text-btn')+action('保存','saveCode','text-btn'))}${state.variant==='错误定位'?note('第 8 行：图片不存在。请检查素材路径。','error'):''}${currentTask().type==='流程任务'?note('当前为流程任务。手动修改并保存脚本后，将转为普通脚本任务。','warn'):''}<div class="editor-toolbar">${icon('code')} task.js <span>JAVASCRIPT · UTF-8</span></div><div class="code-editor"><div class="lines">${Array.from({length:21},(_,i)=>i+1).join('\n')}</div><textarea data-field="code" spellcheck="false" aria-label="JavaScript 脚本内容">${esc(state.draftCode??savedCode)}</textarea></div><div class="editor-bottom"><span data-code-status>Ln 1, Col 1</span><span style="margin-left:auto">${action('API 帮助','navigate:api','text-btn')}${action('清空','modal:clearCode','text-btn')}</span></div><div class="code-keyboard">${['(',')','{','}','[',']',';','"'].map(k=>`<button data-action="insert:${esc(k)}">${esc(k)}</button>`).join('')}</div>${note('提示：长按 API 提示可查看参数与示例。')}`,footer:'',tab:''}),['examples','api','detail'],['默认','错误定位']);
define('examples','脚本示例','edit','按操作类型组织现有 API 示例；每段示例支持复制与插入当前编辑位置。',()=>screen(`${note('选择示例查看用法，也可以直接插入当前脚本。')}${section('基础操作')}${card(row('点击与滑动','click · swipe · sleep','cursor','@example:basic')+row('循环与等待','重复执行与控制间隔','loop','@example:loop'))}${section('识别与素材')}${card(row('找图并点击','images.findImage · click','image','@example:image')+row('找色与区域','颜色匹配及范围限定','color','@example:color')+row('文字识别 OCR','识别屏幕上的文字','search','@example:ocr'))}${section('调试')}${card(row('日志输出','log · toastLog','log','@example:log'))}`,{title:'脚本示例',subtitle:'从一个小例子开始'}),['api','editor']);
define('api','API 示例详情','edit','展示 API 名称、用途、参数和代码；复制与插入具有明确的反馈。',()=>screen(`<div class="summary"><span class="app-icon">${icon('code')}</span><div><h3>查找图片并点击</h3><p>识别 · 图片匹配</p></div></div><div class="content-block"><h4>如何使用</h4><p>从任务素材中读取图片，在屏幕中查找；找到后点击对应坐标。</p></div><div class="diff">const point = images.findImage(<br>&nbsp; captureScreen(),<br>&nbsp; "images/签到按钮.png",<br>&nbsp; { threshold: 0.9 }<br>);<br>if (point) {<br>&nbsp; click(point.x, point.y);<br>}</div>${note('使用前需要截屏能力，点击还需要无障碍服务。素材路径相对于当前任务目录。')}${go('检查运行权限','permissions','text-btn')}`,{title:'找图并点击',subtitle:'API 示例',footer:action('复制代码','copyExample','secondary','copy')+action('插入示例','insertExample','primary','plus')}),['editor','examples','permissions']);
const examples={
  image:{title:'找图并点击',category:'识别 · 图片匹配',description:'从任务素材中读取图片，在当前屏幕中查找；找到后点击对应坐标。',code:'const point = images.findImage(\n  captureScreen(),\n  "images/签到按钮.png",\n  { threshold: 0.9 }\n);\nif (point) {\n  click(point.x, point.y);\n}',note:'需要截屏能力；点击还需要无障碍服务。图片路径相对于当前任务目录。'},
  basic:{title:'点击与滑动',category:'基础 · 坐标操作',description:'点击指定坐标，等待画面变化，再完成一次滑动。',code:'click(540, 1200);\nsleep(500);\nswipe(540, 1800, 540, 600, 500);',note:'需要无障碍服务。坐标和滑动时长应按自己的设备调整。'},
  loop:{title:'循环与等待',category:'基础 · 重复执行',description:'使用 JavaScript 循环重复执行操作，并在两次操作之间等待。',code:'for (let i = 0; i < 3; i++) {\n  click(540, 1200);\n  sleep(1000);\n}',note:'sleep 的参数单位为毫秒。脚本内部循环与整任务循环分别配置。'},
  color:{title:'找色与区域',category:'识别 · 颜色匹配',description:'截取当前画面，在指定区域查找目标颜色。',code:'const point = images.findColor(\n  captureScreen(), "#588c68",\n  { region: [0, 0, 540, 960],\n    threshold: 16 }\n);\nif (point) log(point.x + "," + point.y);',note:'需要截屏能力；region 使用 [x, y, 宽, 高] 格式。'},
  ocr:{title:'文字识别 OCR',category:'识别 · 屏幕文字',description:'初始化文字识别引擎，并读取当前屏幕中的文本。',code:'ocr.init();\nconst text = ocr.recognizeText(\n  captureScreen()\n);\nlog(text);',note:'需要截屏能力。识别速度与结果受画面清晰度影响。'},
  log:{title:'日志输出',category:'调试 · 运行输出',description:'向运行日志输出文字，帮助确认每个操作是否执行。',code:'log("开始执行");\nsleep(500);\ntoastLog("操作已完成");',note:'运行输出可在 APP 日志页与悬浮日志控制台查看。'}
};
