define('assets','任务素材','assets','两列缩略图优先于文件列表，常用导入与截取入口清晰可见；历史原图单独管理。',()=>screen(`<div class="row-between">${pill('4 张任务图片')} ${go('历史素材','asset-history','text-btn')}</div>${state.variant==='空白'||state.assetsEmpty?empty('还没有任务图片','导入按钮截图，或从屏幕中截取模板。','image','截取第一张模板','template-capture'):`<div class="asset-grid" style="margin:18px 0">${assetNames.map((n,i)=>`<button class="asset-card" data-action="asset:${i}">${assetArt(i)}<div class="asset-info"><b>${esc(i===0?state.assetName:n)}</b><small>${i?240:480} × ${i?120:180} px · PNG</small></div></button>`).join('')}</div>`}${section('素材工具')}${card(row('截取模板','框选屏幕内容，保存为任务图片','shot','template-capture')+row('历史素材','裁剪前的原图，随时移回','history','asset-history'))}${note('脚本可使用 images/图片名称.png 引用素材。')}`,{title:'素材管理',subtitle:esc(currentTask().name),actions:action('导入','importAsset','text-btn')}),['asset-detail','template-capture','asset-history'],['默认','空白']);
