function cropCanvas(){return `<div class="crop-stage">${sampleApp()}<div class="selection-box" data-crop-box><i></i><i></i><i></i><i></i></div></div>`;}
function cropValues(){return `<div class="crop-values">${[['X',state.crop.x],['Y',state.crop.y],['宽',state.crop.w],['高',state.crop.h]].map(([k,v])=>`<div class="crop-value"><small>${k}</small>${v}</div>`).join('')}</div>`;}
define('crop','素材裁剪','assets','画布支持拖动选区；原图像素坐标支持精确编辑。覆盖保存前告知历史原图保留方式。',()=>screen(`${cropCanvas()}<div class="row-between"><span class="tiny muted">原图 1080 × 2400 px</span>${action('重选','resetCrop','text-btn')}</div>${section('当前选区','以原图像素为单位')}${cropValues()}<div class="quick-grid">${action('选择整张图片','fullCrop','secondary')}${go('精确调整','crop-exact','secondary')}</div>${note('保存后替换当前素材，原图移入历史素材；脚本引用保持原路径。')}`,{title:'裁剪图片',subtitle:esc(state.assetName),footer:action('保存裁剪','saveCrop','primary','check')}),['crop-exact','asset-history','asset-detail']);
define('crop-exact','精确调整选区','assets','输入原图像素坐标，校验选区边界与最小尺寸，避免出现越界裁剪。',()=>screen(`${note('原图尺寸 1080 × 2400 px，选区必须完整位于原图范围内。')}<div class="quick-grid">${field('起点 X',state.crop.x,'number','cropX')}${field('起点 Y',state.crop.y,'number','cropY')}${field('宽度',state.crop.w,'number','cropW')}${field('高度',state.crop.h,'number','cropH')}</div>${cropCanvas()}`,{title:'精确调整',subtitle:'以原图像素为单位',footer:action('应用选区','applyCrop')}),['crop']);
define('rename-asset','素材重命名','assets','重命名分两步：输入新文件名，然后核对脚本与流程引用。',()=>screen(`${assetArt(state.asset)}${field('新文件名','签到按钮_新版.png','text','assetName','保留 .png 扩展名，名称不能包含路径分隔符。')}${note('下一步会展示受影响的引用，确认后一起更新脚本；流程任务还会同步更新流程和草稿引用。')}`,{title:'重命名素材',subtitle:esc(state.assetName),footer:action('查看引用变更','previewReferences','primary','arrow')}),['asset-refs','asset-detail']);
define('asset-refs','素材引用确认','assets','用前后对照展示引用差异，保留返回修改与确认重命名两个清晰动作。',()=>screen(`${note('将更新 1 处脚本引用。流程任务中的相应引用也会一起更新。')}${section('task.js','第 8 行')}<div class="diff"><div class="removed">− "images/${esc(state.assetName)}"</div><div class="added">+ "images/${esc(state.pendingAssetName||'签到按钮_新版.png')}"</div></div><div class="content-block"><h4>变更后</h4><p>图片使用新文件名，识别逻辑和素材内容保持不变。</p></div>`,{title:'确认引用变更',subtitle:'重命名素材 · 第 2 步',footer:go('返回修改','rename-asset','secondary')+action('确认重命名','renameAsset')}),['rename-asset','asset-detail']);
define('asset-history','历史素材','assets','按时间保留裁剪前原图；移回时明确覆盖当前同名图片，并要求确认。',()=>screen(`${note('移回后恢复原文件名，并覆盖当前同名素材。','warn')}${state.variant==='空白'?empty('暂无历史素材','裁剪图片后，原图会保存在这里。','history'): `${section('今天 · 11 月 16 日')}<div class="content-block">${assetArt(0)}<div class="row-between" style="margin-top:14px"><div><b class="small">${esc(state.assetName)}</b><p class="tiny muted">1080 × 2400 px · 08:26</p></div>${action('移回素材','modal:restoreAsset','text-btn')}</div></div>${section('昨天 · 11 月 15 日')}<div class="content-block"><b class="small">领取奖励.png</b><p class="tiny muted">480 × 320 px · 20:14</p>${action('移回素材','modal:restoreAsset','text-btn')}</div>`}`,{title:'历史素材',subtitle:'裁剪前保留的原始图片'}),['asset-detail','assets'],['默认','空白']);
