function marketCard(m,i,batch=false){return `<button class="market-card" data-action="${batch?'marketSelect':'market'}:${i}" ${batch&&m.tag==='需更新助手'?'disabled':''}><div class="row-between"><span class="app-icon ${m.color}">${icon(m.icon)}</span><div class="item-copy"><h3>${m.name}</h3><span class="tiny muted">${m.author} · v${m.version}</span></div>${batch?check(state.marketSelected.has(i)):icon('chevron','row-arrow')}</div><p>${m.desc}</p><div class="market-meta"><span>${m.kind}</span><span>·</span><span>含脚本与素材</span>${m.tag?pill(m.tag,m.tag==='需更新助手'?'amber':''):''}</div></button>`;}
function marketContent(batch=false){let items=catalog.map((m,i)=>({m,i})).filter(({m})=>(state.marketFilter==='全部'||m.kind===state.marketFilter)&&`${m.name}${m.desc}${m.author}`.toLowerCase().includes(state.marketQuery.toLowerCase()));return `<div class="search">${icon('search')}<input data-field="marketSearch" placeholder="搜索脚本、应用或作者" value="${esc(state.marketQuery)}" aria-label="搜索市场脚本"></div><div class="chips">${['全部','按应用','通用'].map(f=>`<button class="chip ${state.marketFilter===f?'active':''}" data-action="marketFilter:${f}">${f}</button>`).join('')}</div>${batch?`<div class="row-between"><span class="small muted">已选 ${state.marketSelected.size} 个</span>${action('全选当前列表','marketSelectAll','text-btn')}</div>`:''}${state.variant==='加载中'?`<div class="content-block"><div class="skeleton short"></div><div class="skeleton box"></div><div class="skeleton"></div></div>`.repeat(3):state.variant==='加载失败'?empty('暂时连接不上市场','请检查网络，已有任务仍可正常使用。','wifi')+action('重新加载','retryMarket','primary full','loop'):items.length?items.map(({m,i})=>marketCard(m,i,batch)).join(''):empty('没有找到相关脚本','试试其他关键词，或切换分类。','search')}${!batch?action('投稿与反馈说明','sourceLink','text-btn'):note('切换搜索和分类会保留已选项；需更新助手的脚本暂不可选。')}`;}
define('market','脚本市场','market','支持按关键词与分类浏览，保留已导入及版本不兼容状态；失败和加载状态可切换查看。',()=>screen(marketContent(),{title:'脚本市场',subtitle:'好用的自动化，值得分享',actions:go('批量导入','market-batch','text-btn')}),['market-detail','market-batch','tasks'],['默认','加载中','加载失败']);
define('market-detail','市场脚本说明','market','名称、作者、版本、使用说明与所需权限先于导入；已导入时提供打开本地任务入口。',()=>{let m=catalog[state.market];return screen(`<div class="summary"><span class="app-icon ${m.color}">${icon(m.icon)}</span><div><h3>${m.name}</h3><p>${m.author} · v${m.version}</p></div></div><div class="chips">${pill(m.kind)}${pill('需要无障碍')}${pill('需要截屏')}</div><div class="content-block"><h4>脚本介绍</h4><p>${m.desc}</p></div><div class="content-block"><h4>使用步骤</h4><ol><li>在权限页开启依赖的运行能力。</li><li>按说明准备目标应用与图片素材。</li><li>打开悬浮任务面板，选择并执行任务。</li></ol></div>${note('导入后可编辑任务参数与素材，让操作适合自己的设备。')}${card(row('查看源码和素材','assistant-scripts · GitHub','code','@sourceLink')+row('反馈问题','描述设备环境和运行情况','help','@feedbackLink'))}${m.tag==='已导入'?go('打开本地任务','detail','secondary full'):''}`,{title:'脚本说明',subtitle:'脚本市场',footer:m.tag==='需更新助手'?go('更新助手后导入','update','primary','download'):action(m.tag==='已导入'?'更新本地任务':'导入到我的任务','modal:importMarket','primary','download')});},['market','import-progress','detail']);
define('market-batch','市场批量选择','market','跨搜索保留已选项目，底部始终显示导入数量，不兼容版本不可选。',()=>screen(marketContent(true),{title:'批量导入',subtitle:'选择需要的社区脚本',actions:go('取消','market','text-btn'),footer:action(`导入所选（${state.marketSelected.size}）`,'confirmBatch','primary','download')}),['import-confirm','market']);
define('import-confirm','批量导入确认','market','执行前列出新增与覆盖项，覆盖影响解释在同一界面中。',()=>screen(`${note('请确认以下任务。已有任务将覆盖脚本、素材和配置，运行历史保留。','warn')}${section('待导入任务',`${state.marketSelected.size} 个`)}${card([...state.marketSelected].map(i=>row(catalog[i].name,i===0?'覆盖本地「每日签到」':'创建新任务','tasks','market-detail',pill(i===0?'覆盖':'新增',i===0?'amber':''))).join(''))}${note('新任务重名时自动添加编号。单项失败不会影响其他任务继续导入。')}`,{title:'确认批量导入',subtitle:'最后确认一下任务清单',footer:go('返回选择','market-batch','secondary')+action('确认导入','startImport')}),['market-batch','import-progress']);
define('import-progress','导入进度','market','展示整体进度与每项下载、校验、导入状态；当前任务完成后继续下一项。',()=>screen(`<div class="empty" style="padding-top:30px"><div class="spinner"></div><h3>正在准备你的任务</h3><p>下载、校验并导入，请稍候。</p></div><div class="row-between"><b class="small">整体进度</b><span class="tiny muted">1 / ${Math.max(state.marketSelected.size,2)}</span></div><div class="progress"><i style="width:52%"></i></div>${card(row('每日签到助手','已完成校验并导入','check','market',pill('已完成'))+row('通用自动翻页','正在下载 · 52%','download','market',pill('导入中','amber')))}${note('此为原型进度演示，约 2 秒后显示结果。')}`,{title:'正在导入',subtitle:'脚本市场'}),['import-result']);
define('import-result','导入结果','market','成功与失败分开说明；支持重试失败项，返回市场保留搜索筛选。',()=>screen(`${empty(state.variant==='部分失败'?'部分任务已导入':'任务已准备就绪',state.variant==='部分失败'?'1 个成功，1 个失败。成功导入的任务可以立即使用。':'所选任务已导入到你的任务空间。','check')}${card(row('每日签到助手','已覆盖本地任务','check','detail',pill('成功'))+row('通用自动翻页',state.variant==='部分失败'?'网络连接中断，可单独重试':'已创建新任务',state.variant==='部分失败'?'wifi':'check','market',pill(state.variant==='部分失败'?'失败':'成功',state.variant==='部分失败'?'red':'')))}${state.variant==='部分失败'?action('重试失败项','startImport','secondary full','loop'):''}`,{title:'导入结果',footer:go('返回脚本市场','market','primary','arrow')}),['market','detail','import-progress'],['默认','部分失败']);
define('transfer','导入与导出','market','单任务与合集 ZIP 共用入口；说明同名覆盖和分组恢复，文件位置交给系统选择器。',()=>screen(`${hero('留一份安心的备份。','任务、素材和配置，随时带到另一台设备。',pill('本地 ZIP · 自主保存'),'none')}${section('导入')}${card(row('从 ZIP 导入任务','支持单任务与任务合集','download','@importZip'))}${section('导出')}${card(row('导出全部任务',`${tasks.length} 个任务 · 包含分组与执行顺序`,'upload','@exportAll'))}${note('导入会覆盖同名任务的脚本、素材和配置，保留本机运行历史。合集中的分组信息会按备份恢复。','warn')}${note('备份包含任务文件和素材；共享流程模板不随任务导出。请把 ZIP 保存到任务目录之外。')}${section('清理')}${card(row('清空全部任务','删除脚本、素材、运行记录和定时','trash','@modal:clearTasks'))}`,{title:'导入与导出',subtitle:'备份、迁移与整理'}),['tasks','import-result']);
const logs=[['08:30:00','INFO','开始执行：每日签到'],['08:30:00','INFO','第 1 轮 / 共 1 轮'],['08:30:01','INFO','正在识别签到按钮…'],['08:30:02','INFO','找到图片，坐标 (540, 1260)'],['08:30:02','INFO','点击成功'],['08:30:03','INFO','签到完成 ✓'],['08:30:03','INFO','任务结束，耗时 3.2 秒'],['08:31:12','WARN','图片匹配耗时较长，继续等待'],['08:31:15','ERROR','未找到素材：images/奖励.png']];
function logList(compact=false){return `<div class="log-lines">${logs.filter(l=>state.logsFilter==='全部'||l[1]===state.logsFilter).slice(0,compact?6:9).map(([time,level,msg])=>`<div class="log-line ${level==='ERROR'?'error':level==='WARN'?'warning':''}"><time>${time}</time><span class="level">${level}</span><div class="message">${msg}</div></div>`).join('')}</div>`;}
define('logs','实时运行日志','run','清晰的时间、级别和文本层级；保留清空、滚动跟随与回到最新。日志级别筛选为本稿的展示交互。',()=>screen(`<div class="row-between">${pill('<span class="dot"></span> 实时输出')}<span class="tiny muted">最近 ${logs.length} 条</span></div><div class="chips">${['全部','INFO','WARN','ERROR'].map(l=>`<button class="chip ${state.logsFilter===l?'active':''}" data-action="logFilter:${l}">${l==='全部'?'全部':l}</button>`).join('')}</div>${state.variant==='空白'?empty('安静，等待下一次开始','任务运行后的输出会出现在这里。','log'):logList()}${action('回到最新','logBottom','secondary full','download')}`,{title:'运行日志',subtitle:'每一步，都清楚可见',back:false,actions:action('清空','modal:clearLogs','text-btn'),tab:'logs'}),['history','run-detail','console'],['默认','空白']);
define('history','任务运行历史','run','按时间线组织结果、耗时和触发来源；出错记录进入错误详情并可定位脚本。',()=>screen(`${state.variant==='空白'?empty('还没有运行记录','从悬浮面板运行一次任务，结果就会显示在这里。','history'): `${section('今天','3 次运行')}<div class="timeline"><div class="timeline-item"><div class="time">08:30:03 · 定时运行</div><button data-go="run-detail"><div class="row-between"><strong>运行成功</strong>${pill('3.2 秒')}</div><p>完成 1 轮执行 · 所有操作已完成</p></button></div><div class="timeline-item error"><div class="time">08:24:18 · 手动运行</div><button data-action="errorDetail"><div class="row-between"><strong>运行失败</strong>${pill('1.8 秒','red')}</div><p>未找到素材：images/奖励.png</p></button></div><div class="timeline-item"><div class="time">08:20:10 · 手动运行</div><button data-go="run-detail"><div class="row-between"><strong>手动停止</strong>${pill('2.1 秒','gray')}</div><p>用户停止了任务及剩余队列</p></button></div></div>`}`,{title:'运行历史',subtitle:esc(currentTask().name),actions:action('清空','modal:clearHistory','text-btn')}),['run-detail','editor'],['默认','空白']);
define('run-detail','运行结果与错误详情','run','成功显示摘要，失败展示错误与堆栈节选，并直达脚本对应行。',()=>screen(`${empty(state.variant==='失败'?'任务执行遇到问题':'这次任务，顺利完成',state.variant==='失败'?'素材文件不存在，检查图片名称与引用路径后再试。':'每日签到已完成，结果记录在运行历史中。',state.variant==='失败'?'help':'check')}<div class="stat-strip"><div><strong>${state.variant==='失败'?'1.8':'3.2'} s</strong><small>执行耗时</small></div><div><strong>1 轮</strong><small>执行轮次</small></div><div><strong>定时</strong><small>触发来源</small></div></div>${state.variant==='失败'?`<div class="diff"><span class="removed">Error: 图片文件不存在<br>images/奖励.png<br>at task.js:8:15</span></div>${go('查看任务素材','assets','text-btn')}`:`<div class="content-block"><h4>完成时间</h4><p>2026 年 11 月 16 日 · 08:30:03</p><p>签到成功，无需进一步操作。</p></div>`}`,{title:'运行详情',subtitle:esc(currentTask().name),footer:state.variant==='失败'?action('打开脚本并定位','locateError','primary','code'):go('返回运行历史','history','primary')}),['history','editor','assets'],['默认','失败']);
define('permissions','运行准备与权限','permissions','三种能力分别说明用途和状态。缺少权限直接给到对应入口，避免把授权与业务任务混在一起。',()=>screen(`<div class="hero"><div class="row-between"><div><span class="overline">READY WHEN YOU ARE</span><h3 style="font-size:21px">${state.permissions.every(Boolean)?'一切就绪，放心开始':'再一步，就准备好了'}</h3><p>按任务所需，开启对应能力。</p></div><div class="ready-circle">${state.permissions.filter(Boolean).length}/3</div></div></div>${[['无障碍服务','用于点击、滑动、手势和录制操作。','cursor'],['悬浮窗权限','让任务面板和快捷工具出现在其他应用上。','float'],['截屏能力','用于找图、找色、OCR 和截图。','shot']].map(([t,d,ic],i)=>`<div class="permission-card"><div class="row-between"><span class="app-icon">${icon(ic)}</span><div class="item-copy"><h3>${t}</h3>${pill(state.permissions[i]?'已开启':'待设置',state.permissions[i]?'':'amber')}</div>${i===2?go('设置','capture','text-btn'):action(state.permissions[i]?'管理':'去开启',`permission:${i}`,'text-btn')}</div><p>${d}</p></div>`).join('')}${go('服务容易中断？查看保活指引','keepalive','text-btn')}`,{title:'运行准备',subtitle:'能力按需开启，状态一目了然',back:false,tab:'permissions'}),['capture','keepalive']);
define('capture','截屏通道选择','permissions','手动选择系统授权或超级权限；明确当前已保存通道，新通道必须先测试成功。',()=>screen(`${note('当前设置：系统授权截屏。更换方式将在测试成功后保存。')}${section('选择截屏方式')}${choice('系统授权截屏','通过 Android 系统弹窗授权',state.capture==='系统授权截屏','capture:系统授权截屏','phone')}${choice('超级权限截屏','需要设备已获得 Root 权限',state.capture==='超级权限截屏','capture:超级权限截屏','shield')}<div class="content-block"><h4>为什么需要测试？</h4><p>确认当前设备能够获取画面后，再用于找图、找色和 OCR。测试失败会保留原设置。</p></div>${note('仅使用你选择的方式，不会自动切换到另一种截屏方式。')}`,{title:'截屏通道设置',subtitle:'选择适合当前设备的方式',footer:action('确认选择并测试','testCapture','primary','shot')}),['capture-test','permissions']);
define('capture-test','截屏测试结果','permissions','测试中、成功、失败使用同一页面骨架；失败保留原通道，可重试或返回改选。',()=>screen(`${state.variant==='测试中'?`<div class="empty"><div class="spinner"></div><h3>正在截取测试画面</h3><p>系统授权方式可能弹出授权提示，请稍候。</p></div>`:state.variant==='失败'?`${empty('这次测试未通过','未获取到有效画面。原有设置仍保留，可以重新授权或选择其他方式。','shot')}${note('示例原因：系统截屏授权被取消。','error')}`:`${empty('截屏通道已就绪','已成功获取测试画面，新设置已保存。','check')}<div class="content-block"><div class="key-value"><span>所选通道</span><b>${state.capture}</b></div><div class="key-value"><span>画面尺寸</span><b>1080 × 2400 px</b></div></div>`}`,{title:'截屏测试',subtitle:state.capture,footer:state.variant==='测试中'?'':state.variant==='失败'?go('更换方式','capture','secondary')+action('重试测试','testCapture'):go('完成','permissions','primary','check')}),['capture','permissions'],['默认','测试中','失败']);
define('keepalive','后台保活指引','permissions','用可操作的步骤解释后台限制。跳转系统设置前展示 APP 能够提供的上下文。',()=>screen(`${note('如果无障碍服务经常关闭，或定时任务没有按时运行，可依次检查以下设置。')}${[['01','允许后台运行','在应用电池设置中，选择允许后台活动或不限制。'],['02','允许自启动','部分系统需要单独开启自启动与关联启动。'],['03','锁定最近任务','在最近任务列表中锁定雕雕助手，减少被清理。'],['04','重新开启无障碍','确认服务开启，再返回运行准备页检查状态。']].map(([n,t,d])=>`<div class="content-block"><div class="row-between"><span class="overline">STEP ${n}</span>${icon('check')}</div><h4 style="margin-top:12px">${t}</h4><p>${d}</p></div>`).join('')}${note('不同品牌的设置名称可能不同，以设备系统页面为准。')}`,{title:'保活指引',subtitle:'让自动化在后台也可靠运行',footer:action('应用系统设置','osSettings','secondary')+action('重试开启无障碍','permission:0')}),['permissions','schedule']);
define('settings','应用设置','settings','沿用悬浮控制、任务执行、截图识别、快捷入口和版本五组设置，状态信息放在条目内。',()=>screen(`${section('悬浮控制')}<div class="list-card"><div class="setting-row"><span class="app-icon">${icon('float')}</span><div class="item-copy"><div class="title">显示悬浮球</div><div class="desc">在其他应用中快速启动任务</div></div>${toggle(state.showFloat!==false,'showFloat','显示悬浮球')}</div><div class="setting-row"><span class="app-icon">${icon('phone')}</span><div class="item-copy"><div class="title">自动贴边</div><div class="desc">松手后吸附到屏幕边缘</div></div>${toggle(state.snap!==false,'snap','自动贴边')}</div></div>${section('任务执行')}${card(row('多任务执行间隔',`${state.queueInterval??3} 秒 · 从下一次队列执行生效`,'clock','queue-interval'))}${section('截图与识别')}${card(row('截屏通道设置',state.capture+' · 点击更换并测试','shot','capture'))}${section('快捷入口')}${card(row('打开悬浮任务面板','任务队列及快捷工具','float','floating')+row('局域网 Web 编辑',state.webRunning?'服务运行中':'服务未启动','monitor','lan',state.webRunning?pill('运行中'):''))}${section('版本')}${card(row('应用更新','当前版本 0.1.17','download','update',pill('有新版本','amber')))}<div class="tiny muted" style="text-align:center;margin:25px 0 8px">雕雕助手 · 把时间留给更喜欢的事</div>`,{title:'应用设置',subtitle:'按你习惯的方式工作',back:false,tab:'settings'}),['queue-interval','lan','capture','update','floating']);
define('queue-interval','多任务执行间隔','settings','整队列的任务间隔与单任务轮次间隔清楚区分；只接受非负整数秒。',()=>screen(`<div class="content-block"><h4>给任务之间留一点时间</h4><p>多选任务和分组任务按顺序运行时，每个任务完成后，等待指定时间再开始下一个。</p></div>${field('任务间隔 · 秒',state.queueInterval??3,'number','queueInterval','默认 3 秒，设为 0 秒可立即执行下一项。')}<div class="journey" style="margin:26px 0"><span class="pill">任务 A</span>${icon('arrow')}<span class="pill gray">等待 ${state.queueInterval??3} 秒</span>${icon('arrow')}<span class="pill">任务 B</span></div>${note('首个任务立即开始，最后一个结束后不再等待。保存后从下一次启动队列生效。')}`,{title:'多任务执行间隔',subtitle:'适用于多选任务与分组',footer:action('保存设置','saveInterval')}),['settings','float-group']);
define('lan','局域网 Web 编辑','settings','提供服务状态、局域网地址、复制和开关。明确只在同一可信网络访问，流程编排在浏览器中完成。',()=>screen(`<div class="lan-graphic">${icon('phone')}<span class="connection"></span>${icon('monitor')}</div><div style="text-align:center">${pill(state.webRunning?'<span class="dot"></span> 服务运行中':'服务已停止',state.webRunning?'':'gray')}<h3 style="font-size:20px;font-weight:550;margin:17px 0 10px">大一点的屏幕，<br>更自在地编排。</h3><p class="small muted">电脑、平板和手机，同一局域网即可连接。</p></div>${state.webRunning?`<div class="address">http://192.168.1.20:8765/</div>${action('复制访问地址','copyAddress','secondary full','copy')}`:note('启动服务后，这里会显示可在浏览器中打开的地址。')}<div class="content-block"><h4>连接后可以做什么</h4><p>编辑脚本、编排流程、管理任务分组和共享模板、上传素材。</p></div>${note('请在可信网络使用。同一局域网内能够访问此地址的设备都可以编辑任务，用完后可停止服务。','warn')}`,{title:'局域网 Web 编辑',subtitle:'把手机任务连接到浏览器',footer:action(state.webRunning?'停止服务':'启动服务','toggleWeb',state.webRunning?'secondary':'primary',state.webRunning?'stop':'play')}),['settings','editor']);
define('update','应用更新','settings','覆盖检查、新版、下载、增量合成、校验、安装准备、下载中断及非正式签名状态。版本号与包大小为示例。',()=>{let s=state.variant==='默认'?state.updateStage:state.variant;let busy=['检查中','下载中','正在合成','正在校验'].includes(s);return screen(`<div style="text-align:center;padding:20px 0 8px">${bird()}<h3 style="font-size:22px;margin:15px 0 7px">雕雕助手</h3><p class="tiny muted">当前版本 0.1.17</p></div><div class="list-card"><div class="setting-row"><div class="item-copy"><div class="title">自动检查更新</div><div class="desc">及时发现正式版本更新</div></div>${toggle(state.autoUpdate,'autoUpdate','自动检查更新')}</div></div><div class="content-block"><div class="row-between"><h4 style="margin:0">${s==='最新版本'?'已是最新版本':s==='非正式签名'?'当前版本暂不支持应用内更新':'新版本 0.1.18'}</h4>${pill(s==='最新版本'?'已更新':'版本示例','gray')}</div><p style="margin-top:10px">${s==='非正式签名'?'应用内更新仅适用于正式签名版本。':s==='最新版本'?'检查完成，你正在使用最新正式版本。':'优化任务管理体验，提升运行稳定性。'}</p>${s==='下载中'||s==='下载中断'?`<div class="row-between small" style="margin-top:20px"><b>${s==='下载中断'?'下载已中断':'正在下载增量包'}</b><span>68%</span></div><div class="progress"><i style="width:68%"></i></div><p>8.4 MB / 12.4 MB · ${s==='下载中断'?'网络连接中断':'下载中'}</p>`:busy?`<div class="spinner" style="margin-top:25px"></div><p style="text-align:center">${s==='检查中'?'正在检查新版本…':s==='正在合成'?'正在合成安装包…':'正在校验安装包…'}</p>`:s==='准备安装'?note('下载与校验完成，可以安装。'):s==='非正式签名'||s==='最新版本'?'':'<p>完整包 32.8 MB · 优先下载增量包</p>'}${!['非正式签名','最新版本','发现新版','检查中'].includes(s)?`<div class="update-steps">${['下载','合成','校验','安装'].map((v,i)=>`<span class="${i<(s==='准备安装'?4:s==='正在校验'?3:s==='正在合成'?2:1)?'done':''}">${v}</span>`).join('')}</div>`:''}</div>${s==='下载中断'?note('可以重新下载；如果增量更新不可用，可改用完整安装包。','warn'):note('原型使用示例版本和演示进度，不会下载或安装 APK。')}`,{title:'应用更新',subtitle:'保持轻快，持续进步',footer:s==='非正式签名'?'':s==='准备安装'?action('删除安装包','deletePackage','secondary')+action('立即安装','installApp'):s==='下载中断'?action('下载完整包','downloadFull','secondary')+action('立即重试','downloadUpdate'):s==='下载中'?action('取消下载','cancelDownload','secondary'):busy?'':action('检查更新','checkUpdate','secondary')+(s==='最新版本'?'':action('下载更新','downloadUpdate','primary','download'))});},['settings'],['默认','检查中','最新版本','下载中','下载中断','正在合成','正在校验','准备安装','非正式签名']);
function sampleApp(){return `<div class="sample-app"><span class="overline">目标应用 · 示意画面</span><h3>美好的一天，开始了。</h3><p>这里是其他应用的内容</p><div class="sample-block" style="display:grid;place-items:center"><span class="mock-button">立即签到</span></div><div class="sample-grid"><div class="sample-block"></div><div class="sample-block"></div></div><div class="sample-block" style="height:65px"></div></div>`;}
function floatingFrame(content,title='任务面板',subtitle='长按单个任务立即执行',footer='',actions=''){return {body:`<div class="outside-app">${sampleApp()}<div class="float-sheet"><div class="handle"></div>${header(title,subtitle,false,actions||ib('close','navigate:tasks','收起面板'))}<div class="app-pad">${content}</div>${footer?`<div class="footer">${footer}</div>`:''}</div><button class="float-bird" data-action="stopOrOpen" aria-label="悬浮球，双击停止任务">${bird()}</button></div>`,tab:'',footer:''};}
define('floating','悬浮任务面板','float','浮层内选择任务，底部固定执行入口；点选顺序决定多任务队列，长按单个任务可运行。',()=>floatingFrame(`<div class="segmented"><button class="selected" data-go="floating">全部任务</button><button data-go="float-groups">任务分组</button></div><div class="task-list">${tasks.slice(0,4).map((t,i)=>taskRow({...t,desc:state.selected.has(i)?`执行顺序 ${[...state.selected].indexOf(i)+1}`:t.desc,tag:''},i,{select:true})).join('')}</div><div class="row-between">${go('快捷工具','tools','text-btn')}<span class="tiny muted">已选 ${state.selected.size} 个任务</span></div>`,'任务面板','轻触选择 · 长按立即执行',action(`执行所选（${state.selected.size}）`,'runSelected','primary','play')),['float-groups','tools','running']);
define('float-groups','悬浮分组列表','float','延续 APP 的分组信息与顺序；进入分组后默认选择所有成员。',()=>floatingFrame(`<div class="segmented"><button data-go="floating">全部任务</button><button class="selected" data-go="float-groups">任务分组</button></div>${card(row(esc(state.groupName),`${state.members.length} 个任务 · 按组内顺序执行`,'folder','float-group')+row('晚间整理','1 个任务','folder','float-group'))}<div class="row-between">${go('快捷工具','tools','text-btn')}<span class="tiny muted">分组来自任务空间</span></div>`,'分组面板','选择一个分组开始执行'),['float-group','floating','tools']);
define('float-group','悬浮分组详情','float','默认全选，可逐项取消，执行始终使用分组保存顺序。返回按钮回到分组列表。',()=>floatingFrame(`${state.members.length?`<div class="task-list">${state.members.map((id,i)=>tasks[id]?taskRow({...tasks[id],desc:`第 ${i+1} 个执行`,tag:''},id,{select:true}):'').join('')}</div>`:empty('这个分组还没有任务','先在 APP 中添加任务。','folder')}${note('任务间隔 3 秒 · 始终按组内顺序执行')}`,esc(state.groupName),'分组执行',action(`执行所选（${state.members.filter(i=>state.selected.has(i)).length}）`,'runGroup','primary','play'),ib('back','navigate:float-groups','返回分组列表')),['running','float-groups']);
define('running','任务执行中','run','将当前任务、剩余队列和停止入口放在同一浮层；双击悬浮球停止全部队列。',()=>floatingFrame(`<div class="row-between">${pill('<span class="dot"></span> '+(state.variant==='任务间等待'?'等待下一任务':'正在执行'))}<span class="tiny muted">1 / 3</span></div><h3 style="font-size:22px;font-weight:550;margin:22px 0 9px">每日签到</h3><p class="small muted">${state.variant==='任务间等待'?'上一项已完成，3 秒后开始下一项。':'第 1 轮 · 正在查找签到按钮…'}</p><div class="progress"><i style="width:38%"></i></div>${section('接下来')}${card(row('自动领取奖励','等待执行','image','detail',pill('排队中','gray'))+row('阅读小助手','等待执行','book','detail',pill('排队中','gray')))}${go('查看悬浮日志','console','text-btn')}${note('双击悬浮雕雕，可停止当前任务和剩余队列。')}`,'正在运行','任务运行控制',action('停止任务与队列','stopRun','danger','stop')),['console','run-detail','floating'],['默认','任务间等待']);
define('tools','悬浮快捷工具','float','七个现有快捷入口集中成可扫视网格，按取样、截屏、录制和日志组织。',()=>floatingFrame(`${section('屏幕取样')}<div class="tool-grid">${[['point','cursor','取点'],['color','color','取色'],['region','crop','选择范围'],['screenshot','shot','截图'],['record-setup','record','录制操作'],['recording','cursor','纯坐标录制']].map(([p,i,t])=>go(t,p,'tool-tile',i)).join('')}</div>${section('运行调试')}${card(row('悬浮日志','随时查看任务运行输出','log','console'))}${note('取色、截图和带画面的录制需要截屏能力；纯坐标录制不需要截屏授权。')}`,'快捷工具','选好工具，继续当前操作','',ib('back','navigate:floating','返回任务面板')),['point','color','region','screenshot','record-setup','recording','console']);
function picker(mode){const cfg={point:['屏幕取点','拖动十字准星，定位需要点击的位置。','X 540   Y 1260','复制坐标'],color:['屏幕取色','定位取样点，查看并复制颜色值。','#588C68','复制颜色'],region:['选择范围','拖动选框和四角，设置识别区域。','[120, 340, 480, 180]','复制范围'],screenshot:['截取屏幕','框选需要保存的画面区域。','480 × 180 px','保存截图']}[mode];return {body:`<div class="outside-app" data-picker-area>${sampleApp()}${mode==='point'||mode==='color'?'<div class="crosshair"></div>':'<div class="selection-box" data-crop-box><i></i><i></i><i></i><i></i></div>'}<div class="picker-card"><div class="row-between"><h3>${cfg[0]}</h3>${ib('close','navigate:tools','关闭工具')}</div><p>${cfg[1]}</p><div class="row-between"><div class="coordinates" data-coordinate>${mode==='region'?`[${state.crop.x}, ${state.crop.y}, ${state.crop.w}, ${state.crop.h}]`:cfg[2]}</div>${mode==='color'?'<span class="color-swatch"></span>':''}</div>${mode==='color'?'<p>RGB 88, 140, 104 · X 540, Y 1260</p>':''}${action(cfg[3],mode==='screenshot'?'saveScreenshot':`copyPicker:${mode}`,'primary full',mode==='screenshot'?'download':'copy')}</div></div>`,tab:'',footer:''};}
define('point','屏幕取点','float','十字定位与坐标读数分开显示，支持点击示意画面移动取点位置并复制。',()=>picker('point'),['tools','color','region']);
define('color','屏幕取色','float','颜色样本、HEX、RGB 和坐标同时呈现。原型使用固定示例颜色，不访问真实屏幕。',()=>picker('color'),['tools','point']);
define('region','屏幕范围选择','float','选区与 [x, y, 宽, 高] 读数，输出可用于找图、找色或 OCR。',()=>picker('region'),['tools','screenshot']);
define('screenshot','截图与保存','float','选择截图范围后交给 Android 系统文件选择器保存。原型以模拟保存结果代替系统界面。',()=>picker('screenshot'),['tools','template-capture']);
define('record-setup','录制准备','float','完整保留任务名称、记录坐标 / 图片、截图尺寸与页面范围。纯坐标录制仍是单独快捷入口。',()=>screen(`${field('任务名称','录制_1116_093000','text','recordName')}${section('记录方式')}${choice('记录坐标','记录点击位置，同时导出备用图片素材',state.recordMode==='记录坐标','recordMode:记录坐标','cursor')}${choice('记录图片','保存图片，回放时通过找图定位',state.recordMode==='记录图片','recordMode:记录图片','image')}<div class="quick-grid">${field('截图宽度 · px',100,'number','recordW')}${field('截图高度 · px',100,'number','recordH')}</div><div class="quick-grid">${field('页面范围宽 · px',300,'number','regionW')}${field('页面范围高 · px',300,'number','regionH')}</div>${note('截图尺寸 20～500 px，页面范围须覆盖截图。录制会在当前应用执行操作；无截屏能力可使用纯坐标录制。')}`,{title:'录制操作',subtitle:'先准备好，再开始记录',footer:action('显示录制悬浮条','startRecord','primary','record')}),['recording','tools']);
define('recording','录制悬浮条','float','紧凑控制条包含录制状态、步骤计数、暂停 / 继续和完成。完成后保存任务。',()=>({body:`<div class="outside-app">${sampleApp()}<div class="record-bar"><span class="rec-dot" style="${state.recordPaused?'background:#e3bd74':''}"></span><div class="record-text"><b>${state.recordPaused?'已暂停':'正在录制'}</b><br>${state.recordSteps??8} 步 · ${state.pureRecord?'纯坐标录制':state.recordMode}</div>${ib(state.recordPaused?'play':'pause','pauseRecord',state.recordPaused?'继续录制':'暂停录制')}<button class="finish-btn" data-go="record-save">完成</button></div><div class="record-hint">${state.recordPaused?'暂停期间的操作不会被记录':'拖动悬浮条可调整位置，点击画面模拟录制一步'}</div>${state.recordPaused?'':'<div class="tap-ring"></div>'}<button class="primary" style="position:absolute;bottom:85px;left:90px" data-action="recordStep">模拟一次点击</button></div>`,footer:'',tab:''}),['record-save','record-setup','tools']);
define('record-save','完成录制与保存','float','保存名称与录制摘要放在一起；放弃录制需确认，保存后进入任务详情。',()=>screen(`${empty('这段操作，已经记下了','保存为任务，之后就可以自动重复执行。','record')}<div class="stat-strip"><div><strong>${state.recordSteps??8} 步</strong><small>已记录操作</small></div><div><strong>12 s</strong><small>录制时长</small></div><div><strong>${state.pureRecord?'坐标':'图片'}</strong><small>录制素材</small></div></div>${field('任务名称',state.recordName||'录制_1116_093000','text','recordSaveName')}${action('放弃这次录制','modal:discardRecord','text-btn')}`,{title:'完成录制',footer:action('保存为任务','saveRecording','primary','check')}),['detail','recording']);
define('console','悬浮日志控制台','float','与 APP 日志共享层级和错误颜色；悬浮环境保留清空与回到最新，面板可关闭。',()=>floatingFrame(`<div class="row-between">${pill('<span class="dot"></span> 实时日志')}${action('清空','modal:clearLogs','text-btn')}</div>${state.variant==='空白'?empty('等待任务输出','任务运行时，日志会显示在这里。','log'):logList(true)}${action('回到最新','logBottom','secondary full','download')}`,'运行控制台','当前任务 · 每日签到','',ib('close','navigate:tools','关闭悬浮日志')),['logs','running','tools'],['默认','空白']);
define('confirmations','操作确认与反馈','work','集中展示重命名、删除、未保存、覆盖等关键确认，所有危险操作均需二次确认。',()=>screen(`${note('点击下方条目，检查对应弹窗和按钮状态。')}${card([['重命名任务','renameTask','edit'],['删除单个任务','deleteTask','trash'],['清空全部任务','clearTasks','trash'],['删除分组','deleteGroup','folder'],['移回历史素材','restoreAsset','history'],['保存流程脚本','convertFlow','code'],['离开未保存的编辑器','unsaved','code'],['删除素材','deleteAsset','image'],['导入覆盖任务','importMarket','download']].map(([t,m,i])=>row(t,'确认弹窗示例',i,'@modal:'+m)).join(''))}`,{title:'操作确认',subtitle:'关键动作的完整反馈'}),['detail','group-detail','asset-history','editor']);

function modalHtml(type){let title='',body='',buttons='',center=false;const cancel=action('取消','closeModal','secondary');const confirm=(t,a,cls='primary')=>cancel+action(t,a,cls);switch(type){case'taskMenu':title='任务操作';body=card(row('编辑脚本','task.js','code','editor')+row('循环执行','','loop','loop')+row('定时运行','','clock','schedule')+row('重命名任务','','edit','@modal:renameTask')+row('导出任务 ZIP','','upload','@exportOne')+row('删除任务','','trash','@modal:deleteTask'));break;case'taskTools':title='任务工具';body=card(row('导入与导出','备份与迁移','download','transfer')+row('脚本市场','浏览社区任务','market','market')+row('清空全部任务','移除所有本地任务','trash','@modal:clearTasks'));break;case'groupMenu':title='分组操作';body=card(row('重命名分组','','edit','@modal:renameGroup')+row('删除分组','任务本身会保留','trash','@modal:deleteGroup'));break;case'renameTask':title='重命名任务';body=field('任务名称',currentTask().name,'text','renameTaskName')+note('脚本、素材、历史记录与定时设置一同保留。');buttons=confirm('保存','renameTask');break;case'renameGroup':title='重命名分组';body=field('分组名称',state.groupName,'text','renameGroupName');buttons=confirm('保存','renameGroup');break;case'deleteTask':title='删除这个任务？';body=`<p>「${esc(currentTask().name)}」的脚本、素材和运行历史都会删除，定时任务也会取消。</p><div class="sheet-notice">此操作无法撤销。建议先导出任务 ZIP。</div>`;buttons=confirm('删除任务','deleteTask','danger');break;case'clearTasks':title='清空全部任务？';body=`<p>将删除 ${tasks.length} 个任务的脚本、素材、运行记录及定时设置。此操作无法撤销。</p>`+go('先导出全部任务','transfer','text-btn');buttons=confirm('清空全部','clearTasks','danger');break;case'deleteGroup':title='删除这个分组？';body=`<p>删除「${esc(state.groupName)}」及组内执行顺序，任务本身会保留。此操作无法撤销。</p>`;buttons=confirm('删除分组','deleteGroup','danger');break;case'deleteAsset':title='删除这张素材？';body=`<p>删除「${esc(state.assetName)}」后，引用这张图片的脚本可能无法运行。此操作无法撤销。</p>`;buttons=confirm('删除素材','deleteAsset','danger');break;case'restoreAsset':title='移回历史素材？';body='<p>恢复原文件名并覆盖当前同名图片。请确认当前版本不再需要。</p>';buttons=confirm('覆盖并移回','restoreAsset');break;case'clearCode':title='清空脚本内容？';body='<p>清空编辑区中的内容，只有点击保存后才会修改脚本文件。</p>';buttons=confirm('清空编辑区','clearCode','danger');break;case'unsaved':title='还有未保存的修改';body='<p>离开后，本次对脚本的修改将不会保存。</p>';buttons=action('继续编辑','closeModal','secondary')+action('放弃修改并离开','discardCode','danger');break;case'convertFlow':title='转为普通脚本任务？';body='<p>手动保存生成的 task.js 后，此任务将转为普通脚本任务，不能再使用可视化流程编辑。</p><div class="sheet-notice">想继续编排流程，请在局域网 Web 编辑器中修改并保存。</div>';buttons=confirm('确认转换并保存','confirmSaveCode');break;case'importMarket':title='导入到我的任务';body=field('本地任务名称',catalog[state.market].tag==='已导入'?'每日签到':catalog[state.market].name,'text','importName')+note(catalog[state.market].tag==='已导入'?'将覆盖现有任务的脚本、素材与配置，运行历史保留。':'创建新的本地任务，导入后可以自由编辑。',catalog[state.market].tag==='已导入'?'warn':'');buttons=confirm('确认导入','singleImport');break;case'saveTemplate':title='保存模板';body=field('文件名','新模板.png','text','templateName')+note('保存到任务「'+esc(currentTask().name)+'」的 images/ 目录。');buttons=confirm('保存模板','saveTemplate');break;case'clearLogs':title='清空运行日志？';body='<p>清空当前实时输出，已保存的任务运行历史不受影响。</p>';buttons=confirm('清空日志','clearLogs','danger');break;case'clearHistory':title='清空运行历史？';body='<p>将删除当前任务的所有运行记录，脚本和素材会保留。</p>';buttons=confirm('清空历史','clearHistory','danger');break;case'discardRecord':title='放弃这次录制？';body='<p>已录制的操作尚未保存，放弃后将无法恢复。</p>';buttons=confirm('放弃录制','discardRecord','danger');break;case'system':title=state.systemTitle||'系统操作示意';body=`<p>${state.systemText||'实际 APP 会在这里打开 Android 系统设置。'}</p><div class="sheet-notice">HTML 设计稿仅模拟交互，不调用系统权限、读写设备任务或执行自动化。</div>`;buttons=action('返回','closeModal','secondary')+action('模拟完成','systemDone');break;default:title='操作提示';body='<p>操作已准备就绪。</p>';buttons=action('知道了','closeModal');}
return `<div class="modal-backdrop" data-action="dismissBackdrop"><section class="modal ${center?'centered':''}" role="dialog" aria-modal="true" aria-label="${title}"><div class="handle"></div><h3>${title}</h3>${body}${buttons?`<div class="modal-actions">${buttons}</div>`:''}${!buttons?action('关闭','closeModal','secondary full'):''}</section></div>`;}

function makePhone(page,variant='默认',gallery=false){let previous=state.variant;state.variant=variant;let result;try{result=page.render();}finally{state.variant=previous;}return `<div class="phone" data-screen="${page.id}"><div class="statusbar"><span>9:41</span><span class="camera"></span><span class="signals">${icon('signal')}${icon('wifi')}${icon('battery')}</span></div><main class="phone-body">${result.body}</main>${result.footer?`<div class="footer">${result.footer}</div>`:''}${result.tab?nav(result.tab):''}<div class="home-indicator"></div>${!gallery&&state.modal?modalHtml(state.modal):''}</div>`;}
const getPage=id=>pages.find(p=>p.id===id)||pages[0];
const root=document.getElementById('app');
const formDrafts=new Map();
function restoreForms(){
  document.querySelectorAll('#live-device [data-field]').forEach(el=>{
    if(['code','marketSearch','cropX','cropY','cropW','cropH'].includes(el.dataset.field))return;
    const key=state.page+':'+(state.page==='schedule'?state.schedule+':':'')+el.dataset.field;
    if(formDrafts.has(key))el.value=formDrafts.get(key);
  });
}

function shell(){root.innerHTML=`<aside class="sidebar"><div class="wordmark"><span class="brand-icon">${icon('bird')}</span><span>雕雕助手<small>DESIGN EXPLORATION</small></span></div><div class="side-label">APP REDESIGN / 02</div><nav class="side-nav" aria-label="设计稿分类"><button data-group="all" class="${state.group==='all'?'active':''}">${icon('grid')}全部界面<span>${pages.length}</span></button>${groups.map(([id,n,ic])=>`<button data-group="${id}" class="${state.group===id?'active':''}">${icon(ic)}${n}<span>${pages.filter(p=>p.group===id).length.toString().padStart(2,'0')}</span></button>`).join('')}</nav><div class="side-footer"><span class="dot" style="color:#809d66"></span>基于当前 APP 功能<br>雾蓝 × 暖灰白 · 无紫色方案<br><span style="font:10px monospace;color:#a1ac96">2026.11 · LOCAL PROTOTYPE</span></div></aside><div class="workspace"><header class="deskbar"><div class="breadcrumb">产品设计 <span style="padding:0 11px;color:#bdc7b4">/</span> <b>雕雕助手 · Android</b></div><nav class="view-tabs" aria-label="预览方式">${[['overview','界面总览'],['focus','交互预览'],['spec','设计规范']].map(([v,t])=>`<button data-view="${v}" class="${state.view===v?'active':''}">${t}</button>`).join('')}</nav></header><main class="canvas"><div class="intro"><div><div class="eyebrow">THOUGHTFUL AUTOMATION, EVERY DAY.</div><h1>让重复的事，自在完成。</h1><p>清晰的任务空间，轻盈的操作体验。雕雕助手全页面 UI 设计稿 · 雾蓝暖白版。</p></div><div class="revision"><b>CONCEPT 02 · MIST BLUE & IVORY</b><br>${pages.length} 个页面 / 浮层 · ${pages.reduce((s,p)=>s+p.states.length,0)} 个页面状态</div></div><select class="mobile-selector" aria-label="选择页面分类"><option value="all">全部界面（${pages.length}）</option>${groups.map(([id,n])=>`<option value="${id}" ${id===state.group?'selected':''}>${n}</option>`).join('')}</select><div id="content"></div></main></div>`;document.body.classList.toggle('focus-mode',state.view==='focus');renderContent();}
function renderContent(){const content=document.getElementById('content');if(state.view==='overview'){let selected=state.group==='all'?groups:groups.filter(g=>g[0]===state.group);content.innerHTML=`<div class="overview-tools"><div class="search">${icon('search')}<input data-field="pageSearch" placeholder="查找页面，例如：录制、素材…" aria-label="查找设计页面"></div><p>点击任意画板进入交互预览 · 示例数据仅用于设计展示</p></div><div id="boards">${selected.map(([gid,n])=>`<section data-board-group><div class="section-heading"><h2>${n}<span>${gid.toUpperCase()}</span></h2><p>${pages.filter(p=>p.group===gid).length} 个页面与浮层</p></div><div class="gallery">${pages.filter(p=>p.group===gid).map(p=>`<article class="artboard" data-title="${p.title}${p.desc}"><div class="art-label"><b>${p.title}</b><span>${String(pages.indexOf(p)+1).padStart(2,'0')} / ${p.states.length>1?p.states.length+' STATES':'DEFAULT'}</span></div><div class="mini-wrap">${makePhone(p,'默认',true)}<button class="preview-open" data-preview="${p.id}" aria-label="预览${p.title}"></button></div><p class="art-caption">${p.desc}</p></article>`).join('')}</div></section>`).join('')}</div>`;}else if(state.view==='focus'){renderFocus();}else{renderSpec();}}
function renderFocus(){let p=getPage(state.page);document.getElementById('content').innerHTML=`<div class="focus-layout"><div class="focus-device"><div class="focus-topline"><select data-page-select aria-label="切换预览页面">${groups.map(([g,n])=>`<optgroup label="${n}">${pages.filter(x=>x.group===g).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${String(pages.indexOf(x)+1).padStart(2,'0')}　${x.title}</option>`).join('')}</optgroup>`).join('')}</select><span>390 × 820</span></div><div id="live-device">${makePhone(p,state.variant)}</div></div><aside class="inspector"><div class="label">${String(pages.indexOf(p)+1).padStart(2,'0')} / ${p.group.toUpperCase()}</div><h2>${p.title}</h2><p>${p.desc}</p><div class="inspector-section"><h4>页面状态</h4><div class="state-buttons">${p.states.map(s=>`<button class="${s===state.variant?'active':''}" data-variant="${s}">${s}</button>`).join('')}</div></div><div class="inspector-section"><h4>继续探索</h4><div class="related">${p.related.map(id=>`<button data-go="${id}">${getPage(id).title}${icon('arrow')}</button>`).join('')}</div></div><div class="inspector-section"><h4>预览说明</h4><p style="font-size:11px">点击手机内的控件体验流程。表单、选择、排序与确认操作使用演示数据；系统授权、文件操作、任务执行和下载更新均为模拟。</p>${action('重置演示数据','resetDemo','text-btn')}</div><div class="spec-token"><i style="background:#3566a0"></i>雾蓝主色<code>#3566a0</code></div><div class="spec-token"><i style="background:#223047"></i>深蓝灰<code>#223047</code></div><div class="spec-token"><i style="background:#faf9f6;border:1px solid #d7dfcc"></i>页面底色<code>#faf9f6</code></div></aside></div>`;fitPhone();restoreForms();if(state.modal)setTimeout(()=>document.querySelector('#live-device .modal input, #live-device .modal button')?.focus(),10);}
function refreshPhone(){if(state.view!=='focus')return;let old=document.querySelector('#live-device .phone-body')?.scrollTop||0;document.getElementById('live-device').innerHTML=makePhone(getPage(state.page),state.variant);document.querySelector('#live-device .phone-body').scrollTop=old;fitPhone();restoreForms();}
function fitPhone(){const wrap=document.getElementById('live-device');if(!wrap)return;const width=Math.min(390,document.querySelector('.focus-device').clientWidth);wrap.style.width=width+'px';const phone=wrap.querySelector('.phone');if(innerWidth<=600){phone.style.width='100%';phone.style.height=Math.max(610,innerHeight-180)+'px';}layoutCompactOverlays();}
function renderSpec(){document.getElementById('content').innerHTML=`<div class="spec-grid"><section class="spec-card"><div class="eyebrow">01 / COLOR SYSTEM</div><h3>安静的底色，明确的行动</h3><div class="swatches"><span class="swatch" style="background:#223047;color:#ebd9b4">#223047</span><span class="swatch" style="background:#3566a0;color:white">#3566a0</span><span class="swatch" style="background:#ebd9b4">#ebd9b4</span><span class="swatch" style="background:#fff;border:1px solid #e3e8db">#FFFFFF</span></div><p>雾蓝色用于主操作与选中态，深蓝灰用于标题和编辑器；暖灰白承载长时间阅读，沙色仅作少量点缀并呼应品牌形象。绿色、琥珀色与红色分别标记成功、警告与错误。</p><div class="chips">${pill('成功 / 就绪')}${pill('等待 / 注意','amber')}${pill('错误 / 危险','red')}${pill('未设置 / 禁用','gray')}</div></section><section class="spec-card"><div class="eyebrow">02 / TYPE & RHYTHM</div><h3>以信息层级减少寻找</h3><div style="font-size:29px;font-weight:650;letter-spacing:-1px">任务空间</div><p style="font-size:18px;color:#223047;margin-top:15px">每日签到</p><p>正文与控件清楚易读，技术数据使用等宽字体。<br>标题 23 / 18 px · 正文 12–14 px · 辅助 10–11 px<br>间距基准 4 px · 页面边距 20 px · 卡片圆角 16–23 px<br>Android 落地时按 sp / dp 调整，触控热区至少 48 dp。</p></section><section class="spec-card"><div class="eyebrow">03 / COMPONENTS</div><h3>一套组件，贯穿整个 APP</h3><div style="display:flex;gap:10px;flex-wrap:wrap">${go('创建任务','create','primary','plus')}${go('次级操作','detail','secondary')}${action('删除任务','previewDelete','danger')}</div>${choice('系统授权截屏','选中态：边框、底色与圆点同时反馈',true,'navigate:capture','phone')}<div class="row-between">${toggle(true,'specToggle','示例开关')}${check(true)}${pill('服务运行中')}${ib('plus','navigate:create','新建任务')}</div></section><section class="spec-card"><div class="eyebrow">04 / INFORMATION ARCHITECTURE</div><h3>延续熟悉的四个主入口</h3>${nav('tasks')}<p>任务：管理、分组、编辑、市场与备份。<br>日志：实时输出、失败信息与历史排查。<br>权限：运行能力与截屏通道。<br>设置：悬浮控制、间隔、Web 编辑与更新。<br>可视化流程与共享模板管理仍在 Web 端完成。</p></section><section class="spec-card spec-wide"><div class="eyebrow">05 / CONNECTED FLOWS</div><h3>完整流程，逐步可审阅</h3>${[['创建与执行',['tasks','create','detail','editor','floating','running','history']],['素材与引用',['assets','asset-detail','crop','asset-history','rename-asset','asset-refs']],['社区导入',['market','market-batch','import-confirm','import-progress','import-result']],['录制与保存',['tools','record-setup','recording','record-save','detail']],['权限准备',['permissions','capture','capture-test','keepalive']]].map(([t,ids])=>`<p>${t}</p><div class="journey">${ids.map((id,i)=>(i?icon('arrow'):'')+go(getPage(id).title,id,'')).join('')}</div>`).join('')}</section><section class="spec-card spec-wide"><div class="eyebrow">06 / STATES & BOUNDARIES</div><h3>不止是正常状态</h3><p>覆盖任务与分组空白、素材与历史空白、市场加载失败、导入部分失败、截屏测试失败、运行错误、更新中断与安装准备。所有危险操作二次确认；编辑离开保留未保存提示；表单验证聚焦到问题字段。页面切换、Esc 关闭弹窗、键盘聚焦和列表上下调整均可使用。</p><p>这是本地 HTML 设计提案，不修改 Android 代码。系统授权、系统文件选择器与安装器仅展示交接反馈；示例任务、运行统计、市场条目、更新版本和地址均为演示数据。APP 内新增的日志级别筛选、结果详情拆页属于本次 UI 设计建议。</p></section></div>`;}

function navigate(id,push=true){if(!pages.some(p=>p.id===id))return;const from=state.page;if(id==='crop-exact')state.cropOrigin=from; if(push&&state.page!==id)state.history.push(state.page);state.page=id;state.view='focus';state.variant='默认';state.modal=null;if(id==='float-group')state.selected=new Set(state.members);shell();history.replaceState(null,'',`#${id}`);window.scrollTo({top:0});}
function back(){if(state.page==='editor'&&state.codeDirty){state.modal='unsaved';refreshPhone();return;}navigate(state.history.pop()||({detail:'tasks',assets:'detail',market:'tasks',settings:'tasks'}[state.page]||getPage(state.page).related[0]||'tasks'),false);}
function toast(message){const phone=document.querySelector('#live-device .phone');if(!phone)return;phone.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;phone.appendChild(el);setTimeout(()=>el.remove(),3200);}
function val(name){return document.querySelector(`#live-device [data-field="${name}"]`)?.value?.trim()??'';}
function invalid(name,message){let e=document.querySelector(`#live-device [data-field="${name}"]`);if(e){e.setAttribute('aria-invalid','true');e.style.borderColor='#ae4647';e.focus();}toast(message);return false;}
function validateName(name,key,existing=[]){if(!name||name.length>50||/[\\/\x00-\x1f]/.test(name)||name==='.'||name==='..')return invalid(key,'请输入 1～50 字的合法名称，不包含路径符号。');if(existing.includes(name))return invalid(key,'名称已存在，请换一个名称。');return true;}
function numberField(name,min=0){const raw=val(name);if(!/^\d+$/.test(raw)||+raw<min){invalid(name,`请输入不小于 ${min} 的整数。`);return null;}return +raw;}
function system(title,text,kind=''){state.systemTitle=title;state.systemText=text;state.systemKind=kind;state.modal='system';refreshPhone();}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制：'+text);}catch{toast('浏览器限制自动复制，请手动复制：'+text);}}
let timer;
function runImport(single=false){state.singleImport=single;navigate('import-progress');clearTimeout(timer);timer=setTimeout(()=>{if(state.page!=='import-progress')return;const indexes=single?[state.market]:[...state.marketSelected];indexes.forEach(i=>{let m=catalog[i];if(m.tag!=='已导入'){tasks.push({name:single?(state.importName||m.name):m.name,desc:m.desc,icon:m.icon,color:m.color,type:'脚本任务',tag:''});}m.tag='已导入';});navigate('import-result');},1800);}
function handle(act,el){let [a,b,c]=act.split(':');switch(a){case'navigate':navigate(b);break;case'back':back();break;case'modal':state.modal=b;refreshPhone();setTimeout(()=>document.querySelector('#live-device .modal input, #live-device .modal button')?.focus(),0);break;case'closeModal':state.modal=null;refreshPhone();break;case'dismissBackdrop':if(el.classList.contains('modal-backdrop')){state.modal=null;refreshPhone();}break;case'task':state.task=+b;navigate('detail');break;case'openGroup':state.groupName=+b?'晚间整理':'早晨例行';navigate('group-detail');break;case'asset':state.asset=+b;navigate('asset-detail');break;case'template':case'loop':case'schedule':case'capture':case'recordMode':state[a]=b;refreshPhone();break;case'toggle':state[b]=!el.classList.contains('on');el.classList.toggle('on',state[b]);el.setAttribute('aria-checked',state[b]);break;case'createTask':{let n=val('taskName');if(!validateName(n,'taskName',tasks.map(t=>t.name)))return;tasks.push({name:n,desc:state.template==='空白任务'?'从一个小任务开始':state.template,icon:state.template==='签到模板'?'sun':state.template==='找图演示'?'image':'code',color:'',type:'脚本任务',tag:''});state.task=tasks.length-1;state.taskEmpty=false;navigate('detail');toast('任务已创建，选择下一步操作。');break;}case'createGroup':{let n=val('groupName');if(!validateName(n,'groupName'))return;state.groupName=n;state.members=[];state.groupEmpty=false;navigate('group-detail');break;}case'renameTask':{let n=val('renameTaskName');if(!validateName(n,'renameTaskName',tasks.filter((_,i)=>i!==state.task).map(t=>t.name)))return;currentTask().name=n;state.modal=null;refreshPhone();toast('任务已重命名，相关配置一同保留。');break;}case'renameGroup':{let n=val('renameGroupName');if(!validateName(n,'renameGroupName'))return;state.groupName=n;state.modal=null;refreshPhone();toast('分组名称已更新。');break;}case'deleteTask':tasks.splice(state.task,1);state.members=state.members.filter(i=>i!==state.task).map(i=>i>state.task?i-1:i);state.task=0;state.selected=new Set();navigate('tasks');toast('演示任务已删除。');break;case'clearTasks':tasks=[];state.members=[];state.selected=new Set();state.taskEmpty=true;navigate('tasks');toast('演示任务已清空，可重置演示数据。');break;case'deleteGroup':state.groupEmpty=true;navigate('groups');toast('分组已删除，任务保留。');break;case'deleteAsset':state.assetsEmpty=true;navigate('assets');toast('演示素材已删除。');break;case'select':state.selected.has(+b)?state.selected.delete(+b):state.selected.add(+b);refreshPhone();break;case'selectAvailable':{let av=tasks.map((_,i)=>i).filter(i=>!state.members.includes(i));let all=av.every(i=>state.selected.has(i));av.forEach(i=>all?state.selected.delete(i):state.selected.add(i));refreshPhone();break;}case'addMembers':{let ids=[...state.selected].filter(i=>i<tasks.length&&!state.members.includes(i));if(!ids.length){toast('请先选择要添加的任务。');return;}state.members.push(...ids);navigate('group-detail');toast(`已添加 ${ids.length} 个任务。`);break;}case'move':{let i=+b,j=i+(+c);if(j<0||j>=state.members.length)return;[state.members[i],state.members[j]]=[state.members[j],state.members[i]];refreshPhone();toast('分组执行顺序已保存。');break;}case'removeMember':state.members=state.members.filter(i=>i!==+b);refreshPhone();toast('已移出分组，任务保留。');break;case'saveLoop':{if(state.loop==='指定次数'&&numberField('loopCount',1)===null)return;if(state.loop==='指定时长'&&numberField('loopDuration',1)===null)return;if(numberField('loopInterval')===null)return;navigate('detail');toast('循环设置已保存。');break;}case'saveSchedule':{let v=val('scheduleValue');if(state.schedule==='每天固定时刻'?!/^([01]\d|2[0-3]):[0-5]\d$/.test(v):numberField('scheduleValue',state.schedule==='固定间隔'?15:1)===null){invalid('scheduleValue','请填写有效运行时间；固定间隔至少 15 分钟。');return;}currentTask().tag=state.schedule==='每天固定时刻'?`每天 ${v}`:`${v} 分钟${state.schedule==='固定间隔'?'一次':'后'}`;navigate('detail');toast('定时设置已保存。');break;}case'cancelSchedule':currentTask().tag='';navigate('detail');toast('当前定时已取消。');break;case'saveCode':state.draftCode=document.querySelector('[data-field="code"]').value;if(currentTask().type==='流程任务'){state.modal='convertFlow';refreshPhone();}else{savedCode=state.draftCode;state.codeDirty=false;state.draftCode=null;toast('脚本已保存到演示数据。');}break;case'confirmSaveCode':savedCode=state.draftCode??savedCode;state.codeDirty=false;state.draftCode=null;currentTask().type='脚本任务';state.modal=null;refreshPhone();toast('已保存并转换为普通脚本任务。');break;case'discardCode':state.codeDirty=false;state.draftCode=null;state.modal=null;navigate('detail');break;case'clearCode':state.draftCode='';state.codeDirty=true;state.modal=null;refreshPhone();document.querySelector('[data-field="code"]').value='';break;case'insert':{let t=document.querySelector('[data-field="code"]');let pos=t.selectionStart;t.setRangeText(b,pos,t.selectionEnd,'end');t.focus();state.draftCode=t.value;state.codeDirty=true;break;}case'example':state.exampleKind=b;navigate('api');break;case'copyExample':copy(example().code);break;case'insertExample':state.draftCode=(state.draftCode??savedCode)+'\n'+example().code+'\n';state.codeDirty=true;navigate('editor');refreshPhone();toast('示例已插入，请保存脚本。');break;case'previewReferences':{let n=val('assetName');if(!validateName(n,'assetName'))return;state.pendingAssetName=n;navigate('asset-refs');break;}case'renameAsset':state.assetName=state.pendingAssetName||'签到按钮_新版.png';navigate('asset-detail');toast('图片和对应引用已同步更新。');break;case'applyCrop':{let x=numberField('cropX'),y=numberField('cropY'),w=numberField('cropW',1),h=numberField('cropH',1);if([x,y,w,h].includes(null))return;if(x+w>1080||y+h>2400){toast('选区超出原图边界，请调整坐标和尺寸。');return;}state.crop={x,y,w,h};navigate(state.cropOrigin==='template-capture'?'template-capture':'crop');break;}case'resetCrop':state.crop={x:120,y:340,w:480,h:180};refreshPhone();toast('选区已重置。');break;case'fullCrop':state.crop={x:0,y:0,w:1080,h:2400};refreshPhone();break;case'saveCrop':navigate('asset-detail');toast('裁剪已保存，原图已移入历史素材。');break;case'restoreAsset':navigate('assets');toast('历史素材已移回并覆盖同名图片。');break;case'recapture':toast('已重新截取示意画面。');break;case'saveTemplate':{let n=val('templateName');if(!validateName(n,'templateName'))return;state.assetName=n;state.assetsEmpty=false;navigate('assets');toast('模板已保存到当前任务。');break;}case'importAsset':system('导入任务素材','实际 APP 会打开相册或文件选择器，选择图片后导入当前任务。','asset');break;case'market':state.market=+b;navigate('market-detail');break;case'marketFilter':state.marketFilter=b;refreshPhone();break;case'marketSelect':state.marketSelected.has(+b)?state.marketSelected.delete(+b):state.marketSelected.add(+b);refreshPhone();break;case'marketSelectAll':{let ids=catalog.map((m,i)=>({m,i})).filter(({m})=>m.tag!=='需更新助手'&&(state.marketFilter==='全部'||m.kind===state.marketFilter)&&`${m.name}${m.desc}${m.author}`.toLowerCase().includes(state.marketQuery.toLowerCase())).map(x=>x.i);let all=ids.every(i=>state.marketSelected.has(i));ids.forEach(i=>all?state.marketSelected.delete(i):state.marketSelected.add(i));refreshPhone();break;}case'confirmBatch':if(!state.marketSelected.size){toast('请先选择至少一个脚本。');return;}navigate('import-confirm');break;case'startImport':runImport();break;case'singleImport':{let n=val('importName');if(!validateName(n,'importName',catalog[state.market].tag==='已导入'?[]:tasks.map(t=>t.name)))return;state.importName=n;state.marketSelected=new Set([state.market]);runImport(true);break;}case'retryMarket':state.variant='默认';renderFocus();toast('已恢复显示示例市场数据。');break;case'sourceLink':window.open('https://github.com/forestcnz/assistant-scripts','_blank','noopener,noreferrer');break;case'feedbackLink':window.open('https://github.com/forestcnz/assistant-scripts/issues','_blank','noopener,noreferrer');break;case'importZip':system('从 ZIP 导入任务','实际 APP 会打开系统文件选择器，选择单任务或任务合集 ZIP。导入会覆盖同名任务的脚本、素材和配置。','zip');break;case'exportOne':case'exportAll':system('选择备份保存位置',a==='exportAll'?'将打包全部任务、素材、配置和分组顺序，并由系统选择 ZIP 保存位置。':'将打包当前任务脚本、素材和配置，并由系统选择 ZIP 保存位置。','export');break;case'logFilter':state.logsFilter=b;refreshPhone();break;case'logBottom':document.querySelector('#live-device .phone-body')?.scrollTo({top:10000,behavior:'smooth'});toast('已回到最新日志。');break;case'clearLogs':state.variant='空白';state.modal=null;renderFocus();toast('实时日志已清空，运行历史保留。');break;case'clearHistory':state.variant='空白';state.modal=null;renderFocus();toast('运行历史已清空。');break;case'errorDetail':navigate('run-detail');state.variant='失败';renderFocus();break;case'locateError':navigate('editor');state.variant='错误定位';renderFocus();break;case'permission':system('Android 系统权限',+b===0?'实际 APP 会打开无障碍设置，请选择雕雕助手并开启服务。':'实际 APP 会打开悬浮窗权限设置，请允许显示在其他应用上层。','permission:'+b);break;case'osSettings':system('应用系统设置','实际 APP 会打开系统应用详情，可调整电池、后台运行与自启动设置。');break;case'systemDone':{let k=state.systemKind;state.modal=null;if(k.startsWith('permission:')){state.permissions[+k.split(':')[1]]=true;refreshPhone();toast('已模拟开启权限。');}else if(k==='zip'){navigate('import-result');}else if(k==='asset'){state.assetsEmpty=false;refreshPhone();toast('已模拟导入一张图片。');}else if(k==='screenshot'){navigate('tools');toast('已模拟保存截图。');}else if(k==='install'){refreshPhone();toast('已模拟交给系统安装器。');}else{refreshPhone();toast('模拟操作完成。');}break;}case'testCapture':navigate('capture-test');state.variant='测试中';renderFocus();clearTimeout(timer);timer=setTimeout(()=>{if(state.page==='capture-test'&&state.variant==='测试中'){state.variant=state.capture==='超级权限截屏'?'失败':'默认';if(state.variant==='默认')state.permissions[2]=true;renderFocus();}},1500);break;case'saveInterval':{let n=numberField('queueInterval');if(n===null)return;state.queueInterval=n;navigate('settings');toast('设置已保存，从下次队列执行生效。');break;}case'toggleWeb':state.webRunning=!state.webRunning;refreshPhone();toast(state.webRunning?'已模拟启动局域网服务。':'已模拟停止局域网服务。');break;case'copyAddress':copy('http://192.168.1.20:8765/');break;case'checkUpdate':state.variant='检查中';renderFocus();setTimeout(()=>{if(state.page==='update'){state.variant='默认';state.updateStage='发现新版';renderFocus();toast('发现示例新版本。');}},1000);break;case'downloadFull':case'downloadUpdate':state.variant='下载中';renderFocus();clearTimeout(timer);timer=setTimeout(()=>{if(state.page==='update'&&state.variant==='下载中'){state.variant='正在合成';renderFocus();timer=setTimeout(()=>{if(state.page==='update'&&state.variant==='正在合成'){state.variant='正在校验';renderFocus();timer=setTimeout(()=>{if(state.page==='update'&&state.variant==='正在校验'){state.variant='准备安装';renderFocus();}},900);}},900);}},1500);break;case'cancelDownload':case'deletePackage':clearTimeout(timer);state.variant='默认';renderFocus();toast(a==='cancelDownload'?'下载已取消。':'演示安装包已删除。');break;case'installApp':system('安装新版本','实际 APP 会交给 Android 系统安装器，按系统提示完成安装。','install');break;case'runSelected':case'runGroup':if(a==='runGroup'?!state.members.some(i=>state.selected.has(i)):!state.selected.size){toast('请先选择至少一个任务。');return;}navigate('running');break;case'stopRun':navigate('floating');toast('当前任务和剩余队列已停止。');break;case'stopOrOpen':if(state.page==='running'){toast('双击悬浮球停止整个队列。');}else navigate('floating');break;case'copyPicker':copy(b==='color'?'#588C68':b==='region'?`[${state.crop.x}, ${state.crop.y}, ${state.crop.w}, ${state.crop.h}]`:state.pointValue||'[540, 1260]');break;case'saveScreenshot':system('保存截图','实际 APP 会打开系统文件选择器，把当前截图保存为 PNG。','screenshot');break;case'startRecord':{let n=val('recordName');if(!validateName(n,'recordName',tasks.map(t=>t.name)))return;let w=numberField('recordW',20),h=numberField('recordH',20),rw=numberField('regionW',1),rh=numberField('regionH',1);if([w,h,rw,rh].includes(null))return;if(w>500||h>500||rw<w||rh<h){toast('截图尺寸需在 20～500 px，页面范围须覆盖截图。');return;}state.recordName=n;state.recordSteps=0;state.recordPaused=true;state.pureRecord=false;navigate('recording');break;}case'pauseRecord':state.recordPaused=!state.recordPaused;refreshPhone();break;case'recordStep':if(!state.recordPaused){state.recordSteps=(state.recordSteps??8)+1;refreshPhone();}else toast('录制已暂停，点击继续后再记录。');break;case'saveRecording':{let n=val('recordSaveName');if(!validateName(n,'recordSaveName',tasks.map(t=>t.name)))return;tasks.push({name:n,desc:`录制操作 · ${state.recordSteps??8} 步`,icon:'record',color:'blue',type:'脚本任务',tag:''});state.task=tasks.length-1;navigate('detail');toast('录制已保存为任务。');break;}case'discardRecord':navigate('tools');toast('本次录制已放弃。');break;case'previewDelete':navigate('confirmations');state.modal='deleteTask';refreshPhone();break;case'resetDemo':location.hash='tasks';location.reload();break;default:toast('已完成示例操作。');}}

root.addEventListener('click',e=>{if(e.target.closest('.modal')&&e.target.closest('[data-action="dismissBackdrop"]')&&!e.target.closest('.modal [data-action],.modal [data-go]'))return;const p=e.target.closest('[data-preview]');if(p){navigate(p.dataset.preview);return;}const v=e.target.closest('[data-view]');if(v){state.view=v.dataset.view;state.modal=null;shell();return;}const g=e.target.closest('[data-group]');if(g){state.group=g.dataset.group;state.view='overview';shell();window.scrollTo({top:0});return;}const variant=e.target.closest('[data-variant]');if(variant){state.variant=variant.dataset.variant;state.modal=null;renderFocus();return;}const goEl=e.target.closest('[data-go]');if(goEl){if(state.page==='editor'&&state.codeDirty&&goEl.dataset.go!=='examples'&&goEl.dataset.go!=='api'){state.modal='unsaved';refreshPhone();return;}if(goEl.dataset.go==='recording'&&state.page==='tools'){state.pureRecord=true;state.recordPaused=true;state.recordSteps=0;}navigate(goEl.dataset.go);return;}const act=e.target.closest('[data-action]');if(act&&!act.disabled){handle(act.dataset.action,act);return;}const picker=e.target.closest('[data-picker-area]');if(picker&&!e.target.closest('.picker-card')&&['point','color'].includes(state.page)){const r=picker.getBoundingClientRect(),x=Math.round((e.clientX-r.left)/r.width*1080),y=Math.round((e.clientY-r.top)/r.height*2400);state.pointValue=`[${x}, ${y}]`;const cross=picker.querySelector('.crosshair');cross.style.left=(e.clientX-r.left)+'px';cross.style.top=(e.clientY-r.top)+'px';if(state.page==='point')picker.querySelector('[data-coordinate]').textContent=`X ${x}   Y ${y}`;}});
root.addEventListener('input',e=>{let f=e.target.dataset.field;if(f&&!['code','marketSearch','pageSearch'].includes(f))formDrafts.set(state.page+':'+(state.page==='schedule'?state.schedule+':':'')+f,e.target.value);if(f==='code'){state.draftCode=e.target.value;state.codeDirty=true;let before=e.target.value.slice(0,e.target.selectionStart),lines=before.split('\n');document.querySelector('[data-code-status]').textContent=`Ln ${lines.length}, Col ${lines.at(-1).length+1}`;}if(f==='marketSearch'){state.marketQuery=e.target.value;let pos=e.target.selectionStart;refreshPhone();let input=document.querySelector('#live-device [data-field="marketSearch"]');input.focus();input.setSelectionRange(pos,pos);}if(f==='pageSearch'){let q=e.target.value.trim();document.querySelectorAll('.artboard').forEach(a=>a.style.display=a.dataset.title.includes(q)?'':'none');document.querySelectorAll('[data-board-group]').forEach(g=>g.style.display=[...g.querySelectorAll('.artboard')].some(a=>a.style.display!=='none')?'':'none');}});
root.addEventListener('change',e=>{if(e.target.matches('[data-page-select]'))navigate(e.target.value);if(e.target.classList.contains('mobile-selector')){state.group=e.target.value;state.view='overview';shell();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;refreshPhone();}if(e.key==='Tab'&&state.modal){let all=[...document.querySelectorAll('#live-device .modal button,#live-device .modal input,#live-device .modal select')].filter(x=>!x.disabled);if(!all.length)return;if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0].focus();}}if((e.ctrlKey||e.metaKey)&&e.key==='s'&&state.page==='editor'&&state.view==='focus'){e.preventDefault();handle('saveCode');}});
root.addEventListener('dblclick',e=>{if(e.target.closest('.float-bird')&&state.page==='running')handle('stopRun');});
let dragIndex=null;
root.addEventListener('dragstart',e=>{let row=e.target.closest('[data-task-index]');if(row&&state.view==='focus'){dragIndex=+row.dataset.taskIndex;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragIndex));}});
root.addEventListener('dragover',e=>{if(e.target.closest('[data-task-index]'))e.preventDefault();});
root.addEventListener('drop',e=>{let r=e.target.closest('[data-task-index]');if(!r||dragIndex===null)return;e.preventDefault();let target=+r.dataset.taskIndex;if(state.page==='group-detail'){let from=state.members.indexOf(dragIndex),to=state.members.indexOf(target);state.members.splice(to,0,state.members.splice(from,1)[0]);}else if(state.page==='tasks'){const old=[...tasks];tasks.splice(target,0,tasks.splice(dragIndex,1)[0]);state.members=state.members.map(i=>tasks.indexOf(old[i]));}dragIndex=null;refreshPhone();toast('顺序已保存。');});
let selectionDrag=null;
root.addEventListener('pointerdown',e=>{let box=e.target.closest('#live-device [data-crop-box]');if(!box)return;let parent=box.parentElement;selectionDrag={box,parent,x:e.clientX,y:e.clientY,left:box.offsetLeft,top:box.offsetTop,width:box.offsetWidth,height:box.offsetHeight,resize:e.target.tagName==='I',corner:[...box.children].indexOf(e.target)};box.setPointerCapture(e.pointerId);e.preventDefault();});
root.addEventListener('pointermove',e=>{if(!selectionDrag)return;let d=selectionDrag,dx=e.clientX-d.x,dy=e.clientY-d.y;let l=d.left,t=d.top,w=d.width,h=d.height;if(d.resize){if([0,2].includes(d.corner)){l+=dx;w-=dx;}else w+=dx;if([0,1].includes(d.corner)){t+=dy;h-=dy;}else h+=dy;}else{l+=dx;t+=dy;}l=Math.max(0,Math.min(l,d.parent.clientWidth-25));t=Math.max(0,Math.min(t,d.parent.clientHeight-25));w=Math.max(25,Math.min(w,d.parent.clientWidth-l));h=Math.max(25,Math.min(h,d.parent.clientHeight-t));d.box.style.left=l+'px';d.box.style.top=t+'px';d.box.style.width=w+'px';d.box.style.height=h+'px';state.crop={x:Math.round(l/d.parent.clientWidth*1080),y:Math.round(t/d.parent.clientHeight*2400),w:Math.round(w/d.parent.clientWidth*1080),h:Math.round(h/d.parent.clientHeight*2400)};const values=document.querySelector('#live-device .crop-values');if(values)values.outerHTML=cropValues();const coords=document.querySelector('#live-device [data-coordinate]');if(coords&&state.page==='region')coords.textContent=`[${state.crop.x}, ${state.crop.y}, ${state.crop.w}, ${state.crop.h}]`;});
root.addEventListener('pointerup',()=>selectionDrag=null);root.addEventListener('pointercancel',()=>selectionDrag=null);
window.addEventListener('resize',fitPhone);
window.addEventListener('hashchange',()=>{let id=location.hash.slice(1);if(pages.some(p=>p.id===id)&&state.page!==id)navigate(id,false);});
const hash=location.hash.slice(1);if(pages.some(p=>p.id===hash)){state.page=hash;state.view='focus';}
shell();
// Read-only inspection surface for QA and coverage review.
window.prototypeReview={pages:pages.map(({id,title,group,states,related})=>({id,title,group,states,related})),navigate,get state(){return state;}};
